import ctypes

def gsl_fdiv_py(x, y):
    cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.gsl_fdiv.argtypes = [ctypes.c_double, ctypes.c_double]
    gsl.gsl_fdiv.restype = ctypes.c_double
    return gsl.gsl_fdiv(x, y)

def assert_test():
    assert abs(gsl_fdiv_py(10.0, 2.0) - 5.0) < 1e-10
    assert abs(gsl_fdiv_py(-1.0, 4.0) - (-0.25)) < 1e-10
    assert abs(gsl_fdiv_py(0.0, 5.0) - 0.0) < 1e-10
    assert abs(gsl_fdiv_py(7.5, 2.5) - 3.0) < 1e-10
    try:
        gsl_fdiv_py(1.0, 0.0)
        assert False, "Expected division by zero behavior (may return inf or raise error)"
    except:
        pass

if __name__ == "__main__":
    assert_test()
